1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region) from their postcode, falling back to their city.
7	 *
8	 * <p>The postcode is matched against fixed 4-digit ranges (NSW 2000-2099, VIC 3000-3099,
9	 * QLD 4000-4099). When the postcode is absent or falls in no known range, the region is looked up
10	 * in a fixed city-to-region table that pins Sydney -&gt; NSW, Melbourne -&gt; VIC and
11	 * Brisbane -&gt; QLD. Anything that matches neither derives the locality {@code "UNKNOWN"}.
12	 */
13	public final class LocalityLookup {
14	
15	    /** City -&gt; canonical region; anything not listed derives locality {@code "UNKNOWN"}. */
16	    private static final Map<String, String> CITY_REGION =
17	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
18	
19	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
20	    private static final Map<String, int[]> REGION_POSTCODES =
21	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
22	            "QLD", new int[] {4000, 4099});
23	
24	    private LocalityLookup() {
25	    }
26	
27	    /**
28	     * Returns the canonical region for the given postcode and city, preferring the postcode.
29	     *
30	     * <p>The postcode is looked up by range first; only when it is absent or in no known range does
31	     * the city-to-region table decide. This returns the same region for known cities but
32	     * disambiguates cities that share a name.
33	     *
34	     * @param postcode the owner's stored postcode, or {@code null}
35	     * @param city the owner's stored city, or {@code null}
36	     * @return the canonical region string, or {@code "UNKNOWN"} when neither postcode nor city maps
37	     */
38	    public static String forPostcodeAndCity(String postcode, String city) {
39	        String region = forPostcode(postcode);
40	        return region != null ? region : forCity(city);
41	    }
42	
43	    /**
44	     * Returns the canonical region for the given city, or {@code "UNKNOWN"} when the city is not in
45	     * the fixed city-to-region table (including a {@code null} city).
46	     *
47	     * @param city the owner's stored city, or {@code null}
48	     * @return the canonical region string, or {@code "UNKNOWN"} when the city is not in the table
49	     */
50	    public static String forCity(String city) {
51	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
52	    }
53	
54	    /**
55	     * Returns the canonical region whose postcode range contains the given postcode, or
56	     * {@code null} when the postcode is absent, non-numeric, or in no known range.
57	     */
58	    private static String forPostcode(String postcode) {
59	        if (postcode == null) {
60	            return null;
61	        }
62	        int value;
63	        try {
64	            value = Integer.parseInt(postcode.trim());
65	        }
66	        catch (NumberFormatException ex) {
67	            return null;
68	        }
69	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
70	            int[] range = entry.getValue();
71	            if (value >= range[0] && value <= range[1]) {
72	                return entry.getKey();
73	            }
74	        }
75	        return null;
76	    }
77	}
