66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
73	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
74	     * stored lower-cased.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** A well-formed postcode: exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
84	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
85	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
86	     */
87	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
88	        "NSW", new int[] {2000, 2099},
89	        "VIC", new int[] {3000, 3099},
90	        "QLD", new int[] {4000, 4099});
91	
92	    /** Dedicated audit logger; one line is emitted per successful owner create. */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * The maximum number of owners a single city may contain. Once a city already holds this many
97	     * owners, any further create naming that city is rejected as a conflict.
98	     */
99	    private static final int MAX_OWNERS_PER_CITY = 50;
100	
101	    /**
102	     * The maximum number of owners that may be registered in a single day. Once this many owners
103	     * already carry today's registration date, any further create is rejected as too many requests.
104	     */
105	    private static final int MAX_OWNERS_PER_DAY = 100;
106	
107	    /**
108	     * The number of owners that must already be registered on today's business day before a response
109	     * carries a bulk-signup warning. Once more than this many owners already carry today's
110	     * registration date, responses set {@code bulkSignupWarning} true.
111	     */
112	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
113	
114	    private final ClinicService clinicService;
115	
116	    private final OwnerMapper ownerMapper;
117	
118	    private final PetMapper petMapper;
119	
120	    private final VisitMapper visitMapper;
121	
122	    public OwnerRestControllerV1(ClinicService clinicService,
123	                                 OwnerMapper ownerMapper,
124	                                 PetMapper petMapper,
125	                                 VisitMapper visitMapper) {
126	        this.clinicService = clinicService;
127	        this.ownerMapper = ownerMapper;
128	        this.petMapper = petMapper;
129	        this.visitMapper = visitMapper;
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
135	        Collection<Owner> owners;
136	        if (lastName != null) {
137	            owners = this.clinicService.findOwnerByLastName(lastName);
138	        } else {
139	            owners = this.clinicService.findAllOwners();
140	        }
141	        if (owners.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        OwnerDto ownerDto = toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
157	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
