338	    /**
339	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
340	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
341	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
342	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
343	     * more owners the create is rejected as a conflict.
344	     *
345	     * @param city the city of the owner being created
346	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
347	     */
348	    /**
349	     * Rejects an owner create once the maximum number of owners have already been registered on the
350	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
351	     * which is always a business day (a weekend effective date is rolled forward to the following
352	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
353	     * business day the create is rejected as too many requests. Because a weekend effective date is
354	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
355	     *
356	     * @param businessDay the adjusted business day the owner being created would be registered on
357	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
358	     */
359	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
360	        long ownersOnDay = this.clinicService.findAllOwners().stream()
361	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
362	            .count();
363	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
364	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
365	        }
366	    }
