411	    /**
412	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
413	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
414	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
415	     * of owners already in that city (e.g. 'SYD-SMI-0007').
416	     *
417	     * @param city the owner's city
418	     * @param lastName the owner's last name
419	     * @return the formatted customer code
420	     */
421	    private String generateCustomerCode(String city, String lastName) {
422	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
423	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
424	        String normalizedCity = normalizeHouseholdField(city);
425	        int sequence = (int) this.clinicService.findAllOwners().stream()
426	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
427	            .count() + 1;
428	        return String.format("%s-%s-%04d", city3, last3, sequence);
429	    }
